// candela_typed_p4.c: the gallery's Typed arm (PICOCALC-CANDELA-TYPED). Candela's kernel and the gallery's scene
// sections in Typed (apps/typed/candela-gallery, generated by tools/gen/candela/kernel-typed.mjs) are compiled to RV32
// on the handheld the first time the gallery renders with this arm (later uses read the module from the compiled-module
// cache, PICOCALC-COMPILE-CACHE), relocated as an ELF module, and bound to the
// renderer core (nucleus/candela_gallery.c) as two cg_instances, cgt_gallery and cgts_gallery (the program renders
// RGB and spectral scenes alike; the core pairs a scene with an instance of its mode). The C++ kernel (cg, cgs) stays
// in the firmware as the benchmark arm; candela_gallery_p4.c chooses between them.
//
// Memory: the program's arena (its kernel record K at word 0, the GGX and sky tables; vectors and structs are value
// records on the stack since PICOCALC-CANDELA-KERNEL-CODEGEN), laid out from its cdlLayout cells; a line buffer; the
// scene's five row buffers. Typed buffers carry their capacity in UTF-16 units in their first word.
#include "candela_gallery.h"
#include "esp_elf.h"
#include "esp_heap_caps.h"
#include "esp_task_wdt.h"
#include "esp_timer.h"
#include "freertos/FreeRTOS.h"
#include "freertos/semphr.h"
#include "freertos/task.h"
#include "p4.h"
#include "typed_apps.h"
#include <inttypes.h>
#include <stdio.h>
#include <string.h>

// The task watchdog's configuration as sdkconfig sets it, restored after the compile.
#if CONFIG_ESP_TASK_WDT_PANIC
#define WDT_PANIC true
#else
#define WDT_PANIC false
#endif
#ifndef CONFIG_ESP_TASK_WDT_CHECK_IDLE_TASK_CPU0
#define CONFIG_ESP_TASK_WDT_CHECK_IDLE_TASK_CPU0 0
#endif
#ifndef CONFIG_ESP_TASK_WDT_CHECK_IDLE_TASK_CPU1
#define CONFIG_ESP_TASK_WDT_CHECK_IDLE_TASK_CPU1 0
#endif
#define WDT_IDLE (CONFIG_ESP_TASK_WDT_CHECK_IDLE_TASK_CPU0 | CONFIG_ESP_TASK_WDT_CHECK_IDLE_TASK_CPU1 << 1)

typedef int (*layout_fn)(uint32_t *out);
typedef int (*k_fn)(uint32_t *k);
typedef int (*span_fn)(uint32_t *k, uint32_t *out, int y, int x0, int x1, int frame);
// K's fixed fields (tools/gen/candela/typed/program.mjs K_FIXED): the five row buffers, then scene, spectral, skyOn
enum { K_SCENE = 7, K_SPECTRAL = 8, K_SKY_ON = 9, COMPILE_STACK = 96 * 1024, RELOCATE_STACK = 6 * 1024 };

static esp_elf_t elf;
static volatile bool loaded, failed;
static volatile int64_t load_started_us;
static SemaphoreHandle_t load_lock;   // one load at a time: a digest waits for a load the gallery started
static layout_fn t_layout;
static k_fn t_init, t_sky;
static span_fn t_span;
static uint32_t *arena, *line, *rows[5];
static unsigned arena_words;

static void *psram(size_t n) { return heap_caps_aligned_calloc(16, 1, (n + 15) & ~(size_t)15, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT); }
static uint32_t *typed_buffer(uint32_t units) {
  uint32_t *b = psram(4 + 2 * (size_t)units);
  if (b) b[0] = units;
  return b;
}

// The compile runs on a task with a QuickJS-sized stack in PSRAM (the gallery's tasks have 24 KB), on core 0 at
// priority 1, while the caller waits. It keeps IDLE0 from running for the whole compile, so core 0's idle task leaves
// the task watchdog meanwhile (at priority 0 it shared the core with IDLE0 and took twice as long: 172 s against 86 s). The relocation disables the caches, which a task may do only from an internal
// stack (cache_utils.c asserts it), so it runs on a second, small task with an internal-RAM stack.
typedef struct { char *image; size_t length; uintptr_t entries[4]; int relocated; TaskHandle_t waiter; } load_job;
static void compile_task(void *arg) {
  load_job *j = arg;
  const p4_typed_app *app = p4_typed_app_find("candela-gallery");
  j->image = app ? p4_typed_app_compile(app, 0, NULL, 0, "bundle", &j->length) : NULL;
  xTaskNotifyGive(j->waiter);
  vTaskSuspend(NULL);
}
static void relocate_task(void *arg) {
  load_job *j = arg;
  char *argv[] = {(char *)j->entries};
  const bool init = esp_elf_init(&elf) == 0;
  j->relocated = init && esp_elf_relocate(&elf, (uint8_t *)j->image, j->length) == 0 && esp_elf_request(&elf, 0, 1, argv) == 0 &&
                 j->entries[0] && j->entries[1] && j->entries[2] && j->entries[3];
  if (init && !j->relocated) esp_elf_deinit(&elf);
  xTaskNotifyGive(j->waiter);
  vTaskSuspend(NULL);
}
static bool on_task(TaskFunction_t f, const char *name, uint32_t stack, UBaseType_t prio, int core, UBaseType_t caps, load_job *j) {
  TaskHandle_t h = NULL;
  if (xTaskCreatePinnedToCoreWithCaps(f, name, stack, j, prio, &h, core, caps) != pdPASS) return false;
  ulTaskNotifyTake(pdTRUE, portMAX_DELAY);
  vTaskDeleteWithCaps(h);
  return true;
}

static bool load_now(char *err, size_t n) {
  if (loaded) return true;
  if (failed) { snprintf(err, n, "the Typed kernel did not compile"); return false; }
  failed = true;
  const int64_t t0 = esp_timer_get_time();
  load_started_us = t0;
  load_job j = {.waiter = xTaskGetCurrentTaskHandle()};
  const esp_task_wdt_config_t wdt = {CONFIG_ESP_TASK_WDT_TIMEOUT_S * 1000, 0, WDT_PANIC};
  esp_task_wdt_reconfigure(&wdt);
  const bool compiled = on_task(compile_task, "cgt-compile", COMPILE_STACK, 1, 0, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT, &j);
  const esp_task_wdt_config_t wdt0 = {CONFIG_ESP_TASK_WDT_TIMEOUT_S * 1000, WDT_IDLE, WDT_PANIC};
  esp_task_wdt_reconfigure(&wdt0);
  if (!compiled) {
    snprintf(err, n, "no stack for the Typed kernel's compile");
    return false;
  }
  const int64_t t1 = esp_timer_get_time();
  const bool ran = j.image && on_task(relocate_task, "cgt-reloc", RELOCATE_STACK, 1, 1, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT, &j);
  free(j.image);
  if (!ran || !j.relocated) {
    snprintf(err, n, j.image ? "the Typed kernel did not relocate" : "the Typed kernel did not compile");
    return false;
  }
  t_layout = (layout_fn)j.entries[0]; t_init = (k_fn)j.entries[1]; t_sky = (k_fn)j.entries[2]; t_span = (span_fn)j.entries[3];
  // the arena from the layout cells: words low, high, pointer count, buffer count, [field, target]..., [header, units]...
  uint32_t *cells = typed_buffer(16);
  const int need = cells ? t_layout(cells) : 0;
  heap_caps_free(cells);
  cells = need > 0 ? typed_buffer((uint32_t)need) : NULL;
  if (!cells || t_layout(cells) != need) { snprintf(err, n, "no memory for the Typed kernel's layout"); return false; }
  const uint16_t *c = (const uint16_t *)(cells + 1);
  arena_words = c[0] | (unsigned)c[1] << 16;
  const unsigned np = c[2], nb = c[3];
  arena = psram(4 * (size_t)arena_words);
  line = typed_buffer(2 * 12 * CG_MAX_SIDE);
  if (!arena || !line) { heap_caps_free(cells); snprintf(err, n, "no memory for the Typed kernel's arena"); return false; }
  for (unsigned i = 0; i < np; i++) arena[c[4 + 2 * i]] = (uint32_t)(uintptr_t)(arena + c[5 + 2 * i]);
  for (unsigned i = 0; i < nb; i++) arena[c[4 + 2 * np + 2 * i]] = c[5 + 2 * np + 2 * i];
  heap_caps_free(cells);
  t_init(arena);
  loaded = true; failed = false;
  printf("CGAL {\"ev\":\"typed-load\",\"compileMs\":%.1f,\"relocateMs\":%.1f,\"moduleBytes\":%u,\"segmentBytes\":%u,\"arenaWords\":%u}\n",
         (t1 - t0) / 1e3, (esp_timer_get_time() - t1) / 1e3, (unsigned)j.length, (unsigned)elf.segment_size, arena_words);
  return true;
}

static portMUX_TYPE lock_init = portMUX_INITIALIZER_UNLOCKED;
static volatile bool loading;
static bool load(char *err, size_t n) {
  if (loaded) return true;
  taskENTER_CRITICAL(&lock_init);
  if (!load_lock) load_lock = xSemaphoreCreateMutex();
  taskEXIT_CRITICAL(&lock_init);
  xSemaphoreTake(load_lock, portMAX_DELAY);
  loading = true;
  const bool ok = load_now(err, n);
  loading = false;
  xSemaphoreGive(load_lock);
  return ok;
}

// The gallery's first use of this arm after a firmware update compiles for about 85 s; every later one reads the
// cache. With the program cached, the gallery loads it before its scene (cgt_ready_now); otherwise it draws with the
// C++ kernel while cgt_poll has it compiled on a task of its own, and cgt_state and cgt_caption say how far it is.
static void load_task(void *arg) {
  char err[96];
  if (!load(err, sizeof err))
    printf("CGAL {\"ev\":\"error\",\"what\":\"typed-load\",\"error\":\"%s\"}\n", err);
  vTaskDeleteWithCaps(NULL);
}
int cgt_state(void) { return loaded ? CGT_READY : failed && !loading ? CGT_FAILED : loading ? CGT_LOADING : CGT_IDLE; }
const char *cgt_state_name(void) { return (const char *const[]){"idle", "loading", "ready", "failed"}[cgt_state()]; }
int cgt_ready_now(void) {
  char err[96];
  if (cgt_state() == CGT_IDLE && p4_typed_app_cached(p4_typed_app_find("candela-gallery"), 0) && !load(err, sizeof err))
    printf("CGAL {\"ev\":\"error\",\"what\":\"typed-load\",\"error\":\"%s\"}\n", err);
  return loaded;
}
int cgt_poll(void) {
  if (cgt_state() == CGT_IDLE) cgt_prepare();
  return loaded;
}
const char *cgt_caption(void) {
  static char caption[32];
  const int state = cgt_state();
  if (state == CGT_LOADING) snprintf(caption, sizeof caption, "C++, Typed compiling %d s", (int)cgt_loading_s());
  else snprintf(caption, sizeof caption, state == CGT_FAILED ? "C++ (Typed failed)" : "C++");
  return caption;
}
double cgt_loading_s(void) { return loading && load_started_us ? (esp_timer_get_time() - load_started_us) / 1e6 : 0; }
// Not while another compile runs or has just run: the painter's compile after a cold boot has a deadline, and two
// compiles share PSRAM's bandwidth.
void cgt_prepare(void) {
  if (loaded || failed || loading || !p4_typed_compiles_quiet(10 * 1000000)) return;
  loading = true;
  if (xTaskCreatePinnedToCoreWithCaps(load_task, "cgt-load", 8 * 1024, NULL, 1, NULL, 0,
                                      MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT) != pdPASS)
    loading = false;
}

// A scene: its rows into five Typed buffers bound in K, its index (gallery.json's order, which is cg_scenes' order and
// the program's scene order), its mode, and the sky table built from its sun and sky rows.
static int begin(const cg_scene_desc *d, const cdl_buffers *b, char *err, size_t n) {
  if (!load(err, n)) return 1;
  const float *src[5] = {b->U, b->O, b->LI, b->BV, b->SD};
  const unsigned count[5] = {b->nU, b->nO, b->nLI, b->nBV, b->nSD};
  for (int k = 0; k < 5; k++) {
    heap_caps_free(rows[k]);
    rows[k] = typed_buffer(8 * count[k]);
    if (!rows[k]) { snprintf(err, n, "no memory for the scene's rows"); return 1; }
    memcpy(rows[k] + 1, src[k], 16 * (size_t)count[k]);
    arena[k] = (uint32_t)(uintptr_t)rows[k];
  }
  arena[K_SCENE] = (uint32_t)(d - cg_scenes);
  arena[K_SPECTRAL] = d->spectral ? 1 : 0;
  arena[K_SKY_ON] = 0;
  t_sky(arena);
  arena[K_SKY_ON] = 1;
  return 0;
}
static int bind(const cdl_buffers *b, const void *sections, void *sky) { (void)b; (void)sections; (void)sky; return 2; }
static unsigned sky_bytes(void) { return 0; }
static void render_span(int y, int x0, int x1, unsigned frame, cdl_pixout *out) {
  t_span(arena, line, y, x0, x1, (int)frame);
  memcpy(out, line + 1, sizeof(cdl_pixout) * (size_t)(x1 - x0));
}

const cg_instance cgt_gallery = {"typed", 0, bind, sky_bytes, render_span, NULL, NULL, NULL, NULL, begin};
const cg_instance cgts_gallery = {"typed-spectral", 1, bind, sky_bytes, render_span, NULL, NULL, NULL, NULL, begin};
